import{_ as p,a0 as n,w as o,s as r,ao as d,I as t,x as e,a1 as a,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"記不住 Linux 命令？這三個工具可以幫你 | LCTT x X-CMD","titleTemplate":false,"description":"記不住 Linux 命令？這三個工具可以幫你 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"記不住 Linux 命令？這三個工具可以幫你 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"記不住 Linux 命令？這三個工具可以幫你 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171020 3 Tools to Help You Remember Linux Commands","title":"記不住 Linux 命令？這三個工具可以幫你","tag":"201711","desc":""},"relativePath":"201711/20171020 3 Tools to Help You Remember Linux Commands.md","filePath":"[post].md"}'),h={name:"201711/20171020 3 Tools to Help You Remember Linux Commands.md"};function u(m,s,c,f,g,b){const i=n("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="記不住-linux-命令-這三個工具可以幫你" tabindex="-1">記不住 Linux 命令？這三個工具可以幫你 <a class="header-anchor" href="#記不住-linux-命令-這三個工具可以幫你" aria-label="Permalink to “記不住 Linux 命令？這三個工具可以幫你”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands-main.jpg?itok=OESH_Evp" alt="apropos" title="apropos"></p><p><em>apropos 工具幾乎默認安裝在每個 Linux 發行版上，它可以幫你找到你所需的命令。</em></p><p>Linux 桌面從開始的簡陋到現在走了很長的路。在我早期使用 Linux 的那段日子裏，掌握命令列是最基本的 —— 即使是在桌面版。不過現在變了，很多人可能從沒用過命令列。但對於 Linux 系統管理員來説，可不能這樣。實際上，對於任何 Linux 管理員（不管是服務器還是桌面），命令列仍是必須的。從管理網絡到系統安全，再到應用和系統設定 —— 沒有什麼工具比命令列更強大。</p><p>但是，實際上……你可以在 Linux 系統裏找到_非常多_命令。比如只看 <code>/usr/bin</code> 目錄，你就可以找到很多命令執行文件（你可以運行 <code>ls/usr/bin/ | wc -l</code> 看一下你的系統裏這個目錄下到底有多少命令）。當然，它們並不全是針對用户的執行文件，但是可以讓你感受下 Linux 命令數量。在我的 Elementary OS 系統裏，目錄 <code>/usr/bin</code> 下有 2029 個可執行文件。儘管我只會用到其中的一小部分，我要怎麼才能記住這一部分呢？</p><p>幸運的是，你可以使用一些工具和技巧，這樣你就不用每天掙扎着去記憶這些命令了。我想和大家分享幾個這樣的小技巧，希望能讓你們能稍微有效地使用命令列（順便節省點腦力）。</p><p>我們從一個系統內置的工具開始介紹，然後再介紹兩個可以安裝的非常實用的程序。</p><h3 id="bash-命令歷史" tabindex="-1">Bash 命令歷史 <a class="header-anchor" href="#bash-命令歷史" aria-label="Permalink to “Bash 命令歷史”">​</a></h3><p>不管你知不知道，Bash（最流行的 Linux shell）會保留你執行過的命令的歷史。想實際操作下看看嗎？有兩種方式。打開終端窗口然後按向上方向鍵。你應該可以看到會有命令出現，一個接一個。一旦你找到了想用的命令，不用修改的話，可以直接按 Enter 鍵執行，或者修改後再按 Enter 鍵。</p><p>要重新執行（或修改一下再執行）之前運行過的命令，這是一個很好的方式。我經常用這個功能。它不僅僅讓我不用去記憶一個命令的所有細節，而且可以不用一遍遍重複地輸入同樣的命令。</p><p>説到 Bash 的命令歷史，如果你執行命令 <code>history</code>，你可以列出你過去執行過的命令列表（圖 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands_1.jpg?itok=2eqm9ii_" alt="Bash 命令歷史" title="Bash history"></p><p><em>圖 1: 你能找到我敲的命令裏的錯誤嗎？</em></p><p>你的 Bash 命令歷史保存的歷史命令的數量可以在 <code>~/.bashrc</code> 文件裏設置。在這個文件裏，你可以找到下面兩行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTSIZE=1000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HISTFILESIZE=2000</span></span></code></pre></div><p><code>HISTSIZE</code> 是命令歷史列表裏記錄的命令的最大數量，而 <code>HISTFILESIZE</code> 是命令歷史文件的最大行數。</p><p>顯然，默認情況下，Bash 會記錄你的 1000 條歷史命令。這已經很多了。有時候，這也被認為是一個安全漏洞。如果你在意的話，你可以隨意減小這個數值，在安全性和實用性之間平衡。如果你不希望 Bash 記錄你的命令歷史，可以將 <code>HISTSIZE</code> 設置為 <code>0</code>。</p><p>如果你修改了 <code>~/.bashrc</code> 文件，記得要登出後再重新登錄（否則改動不會生效）。</p><h3 id="apropos" tabindex="-1">apropos <a class="header-anchor" href="#apropos" aria-label="Permalink to “apropos”">​</a></h3><p>這是第一個我要介紹的工具，可以幫助你記憶 Linux 命令。apropos （意即“關於”）能夠搜索 Linux 幫助文檔來幫你找到你想要的命令。比如説，你不記得你用的發行版用的什麼防火牆工具了。你可以輸入 <code>apropos “firewall” </code>，然後這個工具會返回相關的命令（圖 2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands_2.jpg?itok=MX5zHfet" alt="apropos" title="apropos"></p><p><em>圖 2: 你用的什麼防火牆？</em></p><p>再假如你需要一個操作目錄的命令，但是完全不知道要用哪個呢？輸入 <code>apropos “directory”</code> 就可以列出在幫助文檔裏包含了字符 “directory” 的所有命令（圖 3）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands_3.jpg?itok=ALEsfP4q" alt="apropos directory" title="apropos directory"></p><p><em>圖 3: 可以操作目錄的工具有哪些呢？</em></p><p>apropos 工具在幾乎所有 Linux 發行版裏都會默認安裝。</p><h3 id="fish" tabindex="-1">Fish <a class="header-anchor" href="#fish" aria-label="Permalink to “Fish”">​</a></h3><p>還有另一個能幫助你記憶命令的很好的工具。Fish 是 Linux/Unix/Mac OS 的一個命令列 shell，有一些很好用的功能。</p><ul><li>自動推薦</li><li>VGA 顏色</li><li>完美的腳本支持</li><li>基於網頁的配置</li><li>幫助文檔自動補全</li><li>語法高亮</li><li>以及更多</li></ul><p>自動推薦功能讓 fish 非常方便（特別是你想不起來一些命令的時候）。</p><p>你可能覺得挺好，但是 fish 沒有被默認安裝。對於 Ubuntu（以及它的衍生版），你可以用下面的命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:fish-shell/release-2</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install fish</span></span></code></pre></div><p>對於類 CentOS 系統，可以這樣安裝 fish。用下面的命令增加倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo -s</span></span>
<span class="line"><span>cd /etc/yum.repos.d/</span></span>
<span class="line"><span>wget http://download.opensuse.org/repositories/shells:fish:release:2/CentOS_7/shells:fish:release:2.repo</span></span></code></pre></div><p>用下面的命令更新倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum repolist</span></span>
<span class="line"><span>yum update</span></span></code></pre></div><p>然後用下面的命令安裝 fish：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum install fish</span></span></code></pre></div><p>fish 用起來可能沒你想像的那麼直觀。記住，fish 是一個 shell，所以在使用命令之前你得先登錄進去。在你的終端裏，運行命令 fish 然後你就會看到自己已經打開了一個新的 shell（圖 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/commands_4.jpg?itok=8TBGVhVk" alt="fish shell" title="fish shell"></p><p><em>圖 4: fish 的交互式 shell。</em></p><p>在開始輸入命令的時候，fish 會自動補齊命令。如果推薦的命令不是你想要的，按下鍵盤的 Tab 鍵可以瀏覽更多選擇。如果正好是你想要的，按下鍵盤的向右鍵補齊命令，然後按下 Enter 執行。在用完 fish 後，輸入 exit 來退出 shell。</p><p>Fish 還可以做更多事情，但是這裏只介紹用來幫助你記住命令，自動推薦功能足夠了。</p><h3 id="保持學習" tabindex="-1">保持學習 <a class="header-anchor" href="#保持學習" aria-label="Permalink to “保持學習”">​</a></h3><p>Linux 上有太多的命令了。但你也不用記住所有命令。多虧有 Bash 命令歷史以及像 apropos 和 fish 這樣的工具，你不用消耗太多記憶來回憶那些幫你完成任務的命令。</p><hr>`,46)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/10/3-tools-help-you-remember-linux-commands"},{default:l(()=>[...s[0]||(s[0]=[e("https://www.linux.com/learn/intro-to-linux/2017/10/3-tools-help-you-remember-linux-commands",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=e("作者：",-1)),a(i,{href:"https://www.linux.com/users/jlwallen"},{default:l(()=>[...s[2]||(s[2]=[e("JACK WALLEN",-1)])]),_:1}),s[6]||(s[6]=e(" 譯者：",-1)),a(i,{href:"https://github.com/zpl1025"},{default:l(()=>[...s[3]||(s[3]=[e("zpl1025",-1)])]),_:1}),s[7]||(s[7]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:l(()=>[...s[9]||(s[9]=[e("Linux中國",-1)])]),_:1}),s[12]||(s[12]=e(" 榮譽推出",-1))])])}const y=p(h,[["render",u]]);export{L as __pageData,y as default};
